use std::fs
use std::process

fn main() {
    let mut names: Vec<string> = []
    let mut first = true
    for a in std::env::args() {
        if first {
            first = false
        } else {
            names.push(a)
        }
    }
    if names.len() == 0 {
        println("usage: tally FILE...")
        process::exit(2)
    }
    let mut report = ""
    let mut bad = false
    for n in names {
        match fs::read_to_string(n) {
            Ok(text) => {
                let mut lines = 0
                for c in text.chars() {
                    if c == '\n' {
                        lines += 1
                    }
                }
                let mut words = 0
                for w in text.split_whitespace() {
                    words += 1
                }
                println("${n}: ${lines} lines, ${words} words")
                report = report + "${n} ${lines} ${words}\n"
            }
            Err(e) => {
                println("${n}: cannot read")
                report = report + "${n} -\n"
                bad = true
            }
        }
    }
    fs::write("report.txt", report)
    let back = fs::read_to_string("report.txt").unwrap_or("")
    println("report:")
    print(back)
    if bad {
        process::exit(1)
    }
}

